+  for (let i = 0; i < payload.steps.length; i++) {
+    const step = parseTransactStep(payload.steps[i], `steps[${i}]`);
+    if (!step.ok) return step;
+    steps.push(step.result);
+  }
+  return ok({
+    kind: "transact",
+    protocolVersion,
+    steps: Object.freeze(steps),
+  });
