    fail(
      "DATAFN_NAMESPACE_STORAGE_UNSUPPORTED",
      `Namespace storage plans are supported for PostgreSQL only. Received dialect "${String((input.catalog as { dialect?: string }).dialect)}".`,
    );
  }

