const STYLE_SHIFT: Record<UIFnPresetV1['style'], { hue: number; chroma: number; radius: number }> = {
  nova: { hue: 0, chroma: 0.02, radius: 0 },
  meridian: { hue: 12, chroma: 0.01, radius: 2 },
