const RADIUS_BASE: Record<UIFnPresetV1['radius'], Record<'sm' | 'md' | 'lg' | 'xl', number>> = {
  none: { sm: 0, md: 0, lg: 0, xl: 0 },
  sm: { sm: 2, md: 4, lg: 6, xl: 8 },
