import {
  streamableHttpTarget,
  type McpFnTarget,
} from "@mcpfn/client";
import type { Implementation } from "@modelcontextprotocol/sdk/types.js";

import {
  type McpFnAuthCredential,
  type McpFnAuthCredentialKind,
  type McpFnAuthProviderAdapter,
} from "./auth-core.js";
import { McpFnTestClient, type McpFnTestClientOptions } from "./client.js";

export interface McpFnStaticRemoteAuth {
  headers: HeadersInit;
}

export type McpFnRemoteAuth =
  | McpFnStaticRemoteAuth
  | McpFnAuthCredential
  | McpFnAuthProviderAdapter;

export interface ConnectAuthenticatedHttpTargetOptions {
  url: string | URL;
  auth: McpFnRemoteAuth;
  kind?: McpFnAuthCredentialKind;
  scopes?: string[];
  resource?: string;
  clientInfo?: Implementation;
  client?: McpFnTestClientOptions;
}

export interface ConnectedAuthenticatedHttpTarget {
  client: McpFnTestClient;
  target: McpFnTarget;
  credential?: McpFnAuthCredential;
  close(): Promise<void>;
}

function isAuthProvider(
  value: McpFnRemoteAuth,
): value is McpFnAuthProviderAdapter {
  return typeof (value as McpFnAuthProviderAdapter).issue === "function";
}

function credentialHeaders(
  auth: McpFnStaticRemoteAuth | McpFnAuthCredential,
): HeadersInit {
  return auth.headers;
}

/** Build a Streamable HTTP target from a URL plus explicit request credentials. */
export function authenticatedHttpTarget(
  url: string | URL,
  auth: McpFnStaticRemoteAuth | McpFnAuthCredential,
): McpFnTarget {
  return streamableHttpTarget(url, {
    requestInit: { headers: credentialHeaders(auth) },
  });
}

async function resolveRemoteAuth(
  auth: McpFnRemoteAuth,
  kind: McpFnAuthCredentialKind,
  scopes?: string[],
  resource?: string,
): Promise<{ targetAuth: McpFnStaticRemoteAuth | McpFnAuthCredential; credential?: McpFnAuthCredential }> {
  if (!isAuthProvider(auth)) {
    return { targetAuth: auth, credential: "kind" in auth ? auth : undefined };
  }
  const credential = await auth.issue({ kind, scopes, resource });
  return { targetAuth: credential, credential };
}

/**
 * Connect the production client to a remote MCP URL using an explicit auth
 * provider or header map. Callers never construct McpFnServer or McpFnRegistry.
 */
export async function connectAuthenticatedHttpTarget(
  options: ConnectAuthenticatedHttpTargetOptions,
): Promise<ConnectedAuthenticatedHttpTarget> {
  const { targetAuth, credential } = await resolveRemoteAuth(
    options.auth,
    options.kind ?? (isAuthProvider(options.auth) ? "oauth" : "api-key"),
    options.scopes,
    options.resource,
  );
  const target = authenticatedHttpTarget(options.url, targetAuth);
  const client = await McpFnTestClient.connectTarget(
    target,
    options.clientInfo ?? { name: "mcpfn-remote-target", version: "0.0.1" },
    options.client,
  );
  return {
    client,
    target,
    credential,
    close: async () => {
      await client.close();
      await credential?.dispose?.();
      if (isAuthProvider(options.auth) && credential) {
        await options.auth.revoke?.(credential);
      }
    },
  };
}
import { redactOAuthValue } from "@superfunctions/oauth-core";

import { classifyMcpFnFailure, type McpFnProtocolLayer } from "./host-authorization.js";
import type { McpFnScenarioReport, McpFnScenarioResult } from "./scenarios.js";
import type { McpFnTargetSuiteReport } from "./suite.js";

export interface McpFnLayeredScenarioResult extends McpFnScenarioResult {
  layer?: McpFnProtocolLayer;
}

export interface McpFnJUnitReportOptions {
  name: string;
  results: Array<{
    name: string;
    status: "passed" | "failed" | "incomplete";
    error?: string;
    layer?: McpFnProtocolLayer;
    durationMs?: number;
  }>;
}

function xmlEscape(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

export function annotateScenarioResultLayer(
  result: McpFnScenarioResult,
): McpFnLayeredScenarioResult {
  if (result.status === "passed" || !result.error) return result;
  return { ...result, layer: classifyMcpFnFailure(new Error(result.error)) };
}

export function annotateScenarioReportLayers(
  report: McpFnScenarioReport,
): McpFnScenarioReport & { results: McpFnLayeredScenarioResult[] } {
  return {
    ...report,
    results: report.results.map(annotateScenarioResultLayer),
  };
}

export function annotateTargetSuiteReportLayers(
  report: McpFnTargetSuiteReport,
): McpFnTargetSuiteReport & { results: McpFnLayeredScenarioResult[] } {
  return {
    ...report,
    results: report.results.map(annotateScenarioResultLayer),
  };
}

/** Bounded JUnit XML for CI. Names and messages are redacted before serialization. */
export function createMcpFnJUnitXml(options: McpFnJUnitReportOptions): string {
  const results = options.results.map((result) => {
    const redacted = redactOAuthValue(result) as typeof result;
    return {
      ...redacted,
      name: String(redacted.name),
      error: redacted.error ? String(redacted.error) : undefined,
    };
  });
  const failures = results.filter((result) => result.status === "failed").length;
  const skipped = results.filter((result) => result.status === "incomplete").length;
  const cases = results.map((result) => {
    const classname = result.layer ?? "mcpfn";
    const time = ((result.durationMs ?? 0) / 1_000).toFixed(3);
    const name = xmlEscape(result.name);
    if (result.status === "passed") {
      return `    <testcase classname="${xmlEscape(classname)}" name="${name}" time="${time}"/>`;
    }
    if (result.status === "incomplete") {
      return `    <testcase classname="${xmlEscape(classname)}" name="${name}" time="${time}">\n      <skipped message="${xmlEscape(result.error ?? "incomplete")}"/>\n    </testcase>`;
    }
    return `    <testcase classname="${xmlEscape(classname)}" name="${name}" time="${time}">\n      <failure message="${xmlEscape(result.error ?? "failed")}" type="${xmlEscape(classname)}">${xmlEscape(result.error ?? "failed")}</failure>\n    </testcase>`;
  });
  return [
    `<?xml version="1.0" encoding="UTF-8"?>`,
    `<testsuite name="${xmlEscape(options.name)}" tests="${results.length}" failures="${failures}" skipped="${skipped}">`,
    ...cases,
    `</testsuite>`,
    "",
  ].join("\n");
}

