  status: "complete" | "incomplete";
  ok: boolean;
  total: number;
  passed: number;
  failed: number;
  droppedResults: number;
  incompleteReason?: string;
  profiles: Array<{ id: string; version: string }>;
  results: McpFnClientProfileCaseResult[];
