  expect(extracted.result.protocolVersion).toBe(DATAFN_REQUEST_PROTOCOL_VERSION);
  expect([...extracted.result.selectors]).toEqual([...expected]);

  const parsed = parseDatafnRequest(action, payload);
  expect(parsed.ok).toBe(true);
  if (!parsed.ok) return;
