    );
  });

  it("ignores resource-shaped application filters and records", () => {
    expectSelectors(
      "query",
      {
        resource: "skills",
        version: 1,
        ...APPLICATION_NOISE,
      },
      ["skills"],
    );
  });

  it("rejects a missing query resource", () => {
    expectError("query", { version: 1 }, "DFQL_INVALID", "$.resource");
