  it("rejects prototype-pollution keys on protocol objects", () => {
    expectError(
      "query",
      { resource: "todos", constructor: "nope" },
      "DFQL_INVALID",
      "$",
    );
  });

  it("rejects a non-string query resource", () => {
    expectError("query", { resource: ["todos"] }, "DFQL_INVALID", "$.resource");
  });

