export const PRESET_AXIS_LABELS: Record<PresetAxis, string> = {
  style: 'Style family',
  baseColor: 'Base color',
  theme: 'Semantic theme',
  chartColor: 'Chart palette',
  font: 'Body font',
  headingFont: 'Heading font',
  iconLibrary: 'Icon library',
  radius: 'Radius',
  density: 'Density',
  menuTreatment: 'Menu treatment',
  framework: 'Framework',
  installMode: 'Install mode',
};

export const APPROVED_SUPPORT_MATRIX = {
  templates: ['react-vite'] as const,
  frameworks: ['react'] as const,
  packageManagers: ['npm'] as const,
  installModes: ['package', 'source'] as const,
  partialDomains: ['theme', 'font'] as const,
  encoding: 'self-contained' as const,
  compatibility: 'V1 codes remain decodable for the life of schema version 1. Unknown future versions fail closed.',
};

export type ApprovedTemplate = (typeof APPROVED_SUPPORT_MATRIX.templates)[number];
export type PartialPresetDomain = (typeof APPROVED_SUPPORT_MATRIX.partialDomains)[number];

export const PILOT_ARTIFACTS = [
  'button',
  'field',
  'input',
  'checkbox',
  'switch',
  'select',
  'dialog',
  'menu',
  'tabs',
  'card',
  'table',
] as const;
import {
  PRESET_AXES,
  PRESET_AXIS_LABELS,
  PRESET_DEFAULTS,
  PRESET_FIELD_ORDER,
  compilePreset,
  encodePreset,
  fixtureCss,
  fixtureMarkup,
  normalizePreset,
  presetFromUrl,
  randomPreset,
  themeTokenDocument,
  type PresetAxis,
  type UIFnPresetV1,
} from '@uifn/registry/preset';

const VIEWPORTS = {
  desktop: 1120,
  tablet: 768,
  mobile: 390,
} as const;

function parseState(): UIFnPresetV1 {
  try {
    return presetFromUrl(window.location.href);
  } catch {
    return { ...PRESET_DEFAULTS };
  }
}

function optionControl(axis: PresetAxis, preset: UIFnPresetV1, locked: Set<PresetAxis>): string {
  const options = (PRESET_AXES[axis] as readonly string[]).map((value) => `<option value="${value}" ${preset[axis] === value ? 'selected' : ''}>${value}</option>`).join('');
  return `<label class="axis">
    <span>
      <input type="checkbox" data-lock="${axis}" ${locked.has(axis) ? 'checked' : ''} />
      ${PRESET_AXIS_LABELS[axis]}
    </span>
    <select data-axis="${axis}">${options}</select>
  </label>`;
}

function render(preset: UIFnPresetV1, locked: Set<PresetAxis>, mode: 'light' | 'dark', viewport: keyof typeof VIEWPORTS) {
  const plan = compilePreset(preset);
  const tokens = themeTokenDocument(preset);
  const app = document.querySelector('#app');
  if (!app) return;
  app.innerHTML = `
    <header class="shell-header">
      <div>
        <p class="kicker">uifn Create</p>
        <h1>Versioned presets</h1>
      </div>
      <div class="header-actions">
        <button type="button" data-action="random">Randomize unlocked</button>
        <button type="button" data-action="copy-code">Copy code</button>
        <button type="button" data-action="copy-url">Copy URL</button>
      </div>
    </header>
    <main class="layout">
      <form class="controls" aria-label="Preset axes">
        ${PRESET_FIELD_ORDER.map((axis: PresetAxis) => optionControl(axis, preset, locked)).join('')}
      </form>
      <section class="preview-pane">
        <div class="preview-toolbar">
          <div class="segmented" role="group" aria-label="Color mode">
            <button type="button" data-mode="light" ${mode === 'light' ? 'aria-pressed="true"' : 'aria-pressed="false"'}>Light</button>
            <button type="button" data-mode="dark" ${mode === 'dark' ? 'aria-pressed="true"' : 'aria-pressed="false"'}>Dark</button>
          </div>
          <div class="segmented" role="group" aria-label="Viewport">
            ${Object.keys(VIEWPORTS).map((name) => `<button type="button" data-viewport="${name}" ${viewport === name ? 'aria-pressed="true"' : 'aria-pressed="false"'}>${name}</button>`).join('')}
          </div>
        </div>
        <div class="preview-frame" data-mode="${mode}" style="width:${VIEWPORTS[viewport]}px">
          <style>${plan.css.light}${plan.css.dark}${fixtureCss()}</style>
          <div class="preview-root" data-uifn-mode="${mode}">${fixtureMarkup(plan)}</div>
        </div>
        <section class="outputs">
          <article>
            <h2>New project</h2>
            <pre><code>${plan.commands.init}</code></pre>
          </article>
          <article>
            <h2>Existing project</h2>
            <pre><code>${plan.commands.apply}</code></pre>
            <pre><code>${plan.commands.applyTheme}</code></pre>
          </article>
          <article>
            <h2>Preset code</h2>
            <pre><code>${plan.code}</code></pre>
            <p><a href="${plan.url}">${plan.url}</a></p>
          </article>
          <article>
            <h2>Theme tokens</h2>
            <pre><code>${JSON.stringify(tokens.light, null, 2)}</code></pre>
          </article>
        </section>
      </section>
    </main>
  `;
  const previewRoot = app.querySelector('.preview-root') as HTMLElement | null;
  if (previewRoot) {
    const vars = mode === 'dark' ? plan.theme.darkVars : plan.theme.lightVars;
    Object.entries(vars).forEach(([name, value]) => previewRoot.style.setProperty(name, String(value)));
    previewRoot.style.background = vars['--uifn-color-surface-canvas'];
    previewRoot.style.color = vars['--uifn-color-text-primary'];
    previewRoot.style.fontFamily = vars['--uifn-typography-family-sans'];
  }
}

function syncUrl(preset: UIFnPresetV1) {
  const url = new URL(window.location.href);
  url.searchParams.set('preset', encodePreset(preset));
  window.history.replaceState(null, '', `${url.pathname}${url.search}`);
}

function boot() {
  let preset = parseState();
  const locked = new Set<PresetAxis>(['framework', 'installMode']);
  let mode: 'light' | 'dark' = 'light';
  let viewport: keyof typeof VIEWPORTS = 'desktop';
  const paint = () => {
    syncUrl(preset);
    render(preset, locked, mode, viewport);
  };
  paint();
  document.addEventListener('change', (event) => {
    const target = event.target as HTMLElement;
    const axis = target.getAttribute('data-axis') as PresetAxis | null;
    const lock = target.getAttribute('data-lock') as PresetAxis | null;
    if (axis && target instanceof HTMLSelectElement) {
      preset = normalizePreset({ ...preset, [axis]: target.value });
      paint();
    }
    if (lock && target instanceof HTMLInputElement) {
      if (target.checked) locked.add(lock);
      else locked.delete(lock);
    }
  });
  document.addEventListener('click', async (event) => {
    const target = event.target as HTMLElement;
    const action = target.getAttribute('data-action');
    const nextMode = target.getAttribute('data-mode') as 'light' | 'dark' | null;
    const nextViewport = target.getAttribute('data-viewport') as keyof typeof VIEWPORTS | null;
    if (nextMode) { mode = nextMode; paint(); }
    if (nextViewport) { viewport = nextViewport; paint(); }
    if (action === 'random') { preset = randomPreset({ seed: Date.now(), locks: Object.fromEntries([...locked].map((axis) => [axis, true])), base: preset }); paint(); }
    if (action === 'copy-code') await navigator.clipboard?.writeText(encodePreset(preset));
    if (action === 'copy-url') await navigator.clipboard?.writeText(`${window.location.origin}${window.location.pathname}?preset=${encodePreset(preset)}`);
  });
}

boot();
import { createHash } from 'node:crypto';
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { runCli } from '../cli';
import { encodePreset, normalizePreset } from '../preset';
import { applyPreset, initProject } from '../preset/project';

function snapshot(rootDir: string): string {
  const entries: string[] = [];
  const walk = (relative = '') => {
    if (!existsSync(path.join(rootDir, relative))) return;
    for (const name of readdirSync(path.join(rootDir, relative)).sort()) {
      const child = path.join(relative, name);
      const pathname = path.join(rootDir, child);
      try {
        entries.push(`${child}\0${createHash('sha256').update(readFileSync(pathname)).digest('hex')}`);
      } catch {
        walk(child);
      }
    }
  };
  walk();
  return createHash('sha256').update(entries.join('\n')).digest('hex');
}

async function withProject(callback: (rootDir: string) => Promise<void> | void) {
  const rootDir = mkdtempSync(path.join(os.tmpdir(), 'uifn-preset-cli-'));
  try { await callback(rootDir); } finally { rmSync(rootDir, { recursive: true, force: true }); }
}

describe('preset CLI and project workflows', () => {
  const code = encodePreset({ style: 'atlas', baseColor: 'stone', density: 'compact' });

  it('encodes, decodes, and prints a share URL', async () => {
    const encoded = await runCli(['preset', 'encode', '--style', 'atlas', '--base-color', 'stone', '--density', 'compact', '--json'], { stdout: () => {}, stderr: () => {} });
    expect(encoded.exitCode).toBe(0);
    expect(encoded.result).toMatchObject({ ok: true, code, preset: normalizePreset({ style: 'atlas', baseColor: 'stone', density: 'compact' }) });
    const decoded = await runCli(['preset', 'decode', code, '--json'], { stdout: () => {}, stderr: () => {} });
    expect(decoded.result).toMatchObject({ ok: true, code, url: expect.stringContaining(code) });
  });

  it('initializes a react-vite project from a dry-run plan, then commits idempotently', async () => {
    await withProject(async (parent) => {
      const rootDir = path.join(parent, 'app');
      const dry = initProject({ rootDir, preset: code, dryRun: true });
      expect(dry.ok).toBe(true);
      expect(dry.dryRun).toBe(true);
      expect(existsSync(rootDir)).toBe(false);
      const first = initProject({ rootDir, preset: code });
      expect(first.ok).toBe(true);
      expect(existsSync(path.join(rootDir, '.uifn/preset.json'))).toBe(true);
      expect(readFileSync(path.join(rootDir, 'src/uifn-theme.css'), 'utf8')).toContain('--uifn-color-accent-solid:');
      const after = snapshot(rootDir);
      const second = applyPreset({ rootDir, preset: code });
      expect(second.ok).toBe(true);
      expect(second.written).toEqual([]);
      expect(snapshot(rootDir)).toBe(after);
    });
  });

  it('partially applies theme/font without installing source artifacts', async () => {
    await withProject(async (rootDir) => {
      expect(initProject({ rootDir, preset: encodePreset({ installMode: 'package' }) }).ok).toBe(true);
      expect(existsSync(path.join(rootDir, 'components'))).toBe(false);
      const next = encodePreset({ installMode: 'package', radius: 'xl', font: 'ibm-plex-sans' });
      const result = applyPreset({ rootDir, preset: next, only: ['theme', 'font'] });
      expect(result.ok).toBe(true);
      expect(readFileSync(path.join(rootDir, 'src/uifn-theme.css'), 'utf8')).toContain('IBM Plex Sans');
      expect(existsSync(path.join(rootDir, 'components'))).toBe(false);
    });
  });

  it('rejects dirty consumer edits and interrupted writes restore bytes', async () => {
    await withProject(async (rootDir) => {
      expect(initProject({ rootDir, preset: code }).ok).toBe(true);
      const theme = path.join(rootDir, 'src/uifn-theme.css');
      writeFileSync(theme, '/* consumer edit */\n');
      const before = snapshot(rootDir);
      const conflicted = applyPreset({ rootDir, preset: encodePreset({ style: 'nova' }) });
      expect(conflicted).toMatchObject({ ok: false, error: { code: 'UIFN_REGISTRY_DIRTY_CONFLICT' } });
      expect(snapshot(rootDir)).toBe(before);
    });
    await withProject(async (parent) => {
      const rootDir = path.join(parent, 'interrupted');
      const result = initProject({ rootDir, preset: code, faultAfterWrites: 1 });
      expect(result).toMatchObject({ ok: false, rolledBack: true, error: { code: 'UIFN_REGISTRY_TRANSACTION_INTERRUPTED' } });
      expect(existsSync(path.join(rootDir, 'src/uifn-theme.css'))).toBe(false);
    });
  });

  it('wires init/apply/resolve through the CLI', async () => {
    await withProject(async (rootDir) => {
      const init = await runCli(['init', '--preset', code, '--dry-run', '--json'], { cwd: rootDir, stdout: () => {}, stderr: () => {} });
      expect(init.result).toMatchObject({ ok: true, dryRun: true, plan: { code } });
      const committed = await runCli(['init', '--preset', code, '--json'], { cwd: rootDir, stdout: () => {}, stderr: () => {} });
      expect(committed.exitCode).toBe(0);
      const resolved = await runCli(['preset', 'resolve', '--json'], { cwd: rootDir, stdout: () => {}, stderr: () => {} });
      expect(resolved.result).toMatchObject({ ok: true, code, preset: normalizePreset({ style: 'atlas', baseColor: 'stone', density: 'compact' }) });
    });
  });

  it('rejects encoded svelte/solid values for V1 init/apply', async () => {
    await withProject(async (rootDir) => {
      const svelte = encodePreset({ framework: 'svelte' });
      const result = initProject({ rootDir, preset: svelte, dryRun: true });
      expect(result).toMatchObject({ ok: false, error: { code: 'UIFN_PRESET_UNSUPPORTED_COMBINATION' } });
      expect(existsSync(rootDir) && readdirSync(rootDir).length > 0).toBe(false);
    });
  });

  it('plans source-install artifacts without writing on dry-run', async () => {
    await withProject(async (parent) => {
      const rootDir = path.join(parent, 'source-app');
      const sourceCode = encodePreset({ installMode: 'source' });
      const dry = initProject({ rootDir, preset: sourceCode, dryRun: true });
      expect(dry.ok).toBe(true);
      expect(dry.plan?.artifacts).toEqual(expect.arrayContaining(['button', 'dialog', 'table']));
      expect(existsSync(rootDir)).toBe(false);
      const committed = initProject({ rootDir, preset: sourceCode });
      expect(committed.ok).toBe(true);
      expect(existsSync(path.join(rootDir, '.uifn/preset.json'))).toBe(true);
      expect(existsSync(path.join(rootDir, '.uifn/registry.lock'))).toBe(true);
      expect(existsSync(path.join(rootDir, 'components/uifn/react/button.ts'))).toBe(true);
      const manifest = JSON.parse(readFileSync(path.join(rootDir, 'package.json'), 'utf8')) as { dependencies: Record<string, string>; devDependencies: Record<string, string> };
      expect(manifest.devDependencies.vite).toBeDefined();
      expect(manifest.dependencies['@uifn/react']).toBeDefined();
      expect(committed.plan?.artifacts).toEqual(expect.arrayContaining(['button']));
    });
  });
});

