import {
  PRESET_AXES,
  PRESET_CODE_PREFIX,
  PRESET_DEFAULTS,
  PRESET_FIELD_ORDER,
  PRESET_SCHEMA_VERSION,
  type PresetAxis,
  type UIFnPresetInput,
  type UIFnPresetV1,
} from './schema';
import { UIFnPresetError } from './errors';

const BASE64URL = 'REDACTED';

function crc8(bytes: Uint8Array): number {
  let crc = 0;
  for (const value of bytes) {
    crc ^= value;
    for (let bit = 0; bit < 8; bit += 1) {
      crc = (crc & 0x80) !== 0 ? ((crc << 1) ^ 0x07) & 0xff : (crc << 1) & 0xff;
    }
  }
  return crc;
}

function toBase64Url(bytes: Uint8Array): string {
  let output = '';
  for (let index = 0; index < bytes.length; index += 3) {
    const first = bytes[index];
    const second = index + 1 < bytes.length ? bytes[index + 1] : 0;
    const third = index + 2 < bytes.length ? bytes[index + 2] : 0;
    output += BASE64URL[first >> 2];
    output += BASE64URL[((first & 3) << 4) | (second >> 4)];
    if (index + 1 < bytes.length) output += BASE64URL[((second & 15) << 2) | (third >> 6)];
    if (index + 2 < bytes.length) output += BASE64URL[third & 63];
  }
  return output;
}

function fromBase64Url(value: string): Uint8Array {
  if (!/^[A-Za-z0-9_-]+$/.test(value) || value.length < 4) {
    throw new UIFnPresetError('UIFN_PRESET_CODE_INVALID', 'Preset code is not URL-safe base64.');
  }
  const codes = [...value].map((character) => {
    const code = BASE64URL.indexOf(character);
    if (code < 0) throw new UIFnPresetError('UIFN_PRESET_CODE_INVALID', 'Preset code contains an invalid character.');
    return code;
  });
  const bytes: number[] = [];
  for (let index = 0; index < codes.length; index += 4) {
    const chunk = [codes[index], codes[index + 1] ?? 0, codes[index + 2] ?? 0, codes[index + 3] ?? 0];
    bytes.push(((chunk[0] << 2) | (chunk[1] >> 4)) & 0xff);
    if (index + 2 < codes.length) bytes.push(((chunk[1] << 4) | (chunk[2] >> 2)) & 0xff);
    if (index + 3 < codes.length) bytes.push(((chunk[2] << 6) | chunk[3]) & 0xff);
  }
  return Uint8Array.from(bytes);
}

function assertAxisValue<K extends PresetAxis>(axis: K, value: unknown): (typeof PRESET_AXES)[K][number] {
  const allowed = PRESET_AXES[axis] as readonly string[];
  if (typeof value !== 'string' || !allowed.includes(value)) {
    throw new UIFnPresetError('UIFN_PRESET_UNKNOWN_OPTION', `Unsupported ${axis} option: ${String(value)}.`, {
      axis,
      value,
      allowed,
    });
  }
  return value as (typeof PRESET_AXES)[K][number];
}

export function normalizePreset(input: UIFnPresetInput | UIFnPresetV1 = {}): UIFnPresetV1 {
  if (input && typeof input === 'object') {
    for (const key of Object.keys(input)) {
      if (key === 'version') continue;
      if (!PRESET_FIELD_ORDER.includes(key as PresetAxis)) {
        throw new UIFnPresetError('UIFN_PRESET_UNKNOWN_FIELD', `Unknown preset field: ${key}.`, { field: key });
      }
    }
  }
  const version = input.version ?? PRESET_SCHEMA_VERSION;
  if (version !== PRESET_SCHEMA_VERSION) {
    throw new UIFnPresetError('UIFN_PRESET_UNSUPPORTED_VERSION', `Unsupported preset schema version: ${version}.`, {
      version,
      supported: [PRESET_SCHEMA_VERSION],
    });
  }
  const next = { ...PRESET_DEFAULTS };
  for (const field of PRESET_FIELD_ORDER) {
    const value = input[field];
    if (value !== undefined) next[field] = assertAxisValue(field, value) as never;
  }
  next.version = PRESET_SCHEMA_VERSION;
  return next;
}

export function encodePreset(input: UIFnPresetInput | UIFnPresetV1 = {}): string {
  const preset = normalizePreset(input);
  const payload = Uint8Array.from([
    PRESET_SCHEMA_VERSION,
    ...PRESET_FIELD_ORDER.map((field) => (PRESET_AXES[field] as readonly string[]).indexOf(preset[field])),
  ]);
  const framed = Uint8Array.from([...payload, crc8(payload)]);
  return `${PRESET_CODE_PREFIX}${toBase64Url(framed)}`;
}

export function decodePreset(code: string): UIFnPresetV1 {
  if (typeof code !== 'string' || !code.startsWith(PRESET_CODE_PREFIX)) {
    throw new UIFnPresetError('UIFN_PRESET_CODE_INVALID', 'Preset code is missing the uifn1_ version prefix.');
  }
  const bytes = fromBase64Url(code.slice(PRESET_CODE_PREFIX.length));
  if (bytes.length < PRESET_FIELD_ORDER.length + 2) {
    throw new UIFnPresetError('UIFN_PRESET_CODE_INVALID', 'Preset code is truncated.');
  }
  const payload = bytes.slice(0, PRESET_FIELD_ORDER.length + 1);
  const checksum = bytes[payload.length];
  if (checksum !== crc8(payload)) {
    throw new UIFnPresetError('UIFN_PRESET_CODE_INVALID', 'Preset code failed integrity checks.');
  }
  const version = payload[0];
  if (version !== PRESET_SCHEMA_VERSION) {
    throw new UIFnPresetError('UIFN_PRESET_UNSUPPORTED_VERSION', `Unsupported preset schema version: ${version}.`, {
      version,
      supported: [PRESET_SCHEMA_VERSION],
    });
  }
  const input: UIFnPresetInput = { version: PRESET_SCHEMA_VERSION };
  PRESET_FIELD_ORDER.forEach((field, index) => {
    const options = PRESET_AXES[field] as readonly string[];
    const optionIndex = payload[index + 1];
    if (optionIndex >= options.length) {
      throw new UIFnPresetError('UIFN_PRESET_UNKNOWN_OPTION', `Preset code references an unknown ${field} option.`, {
        axis: field,
        index: optionIndex,
      });
    }
    input[field] = options[optionIndex] as never;
  });
  return normalizePreset(input);
}

export function parsePresetJson(source: string): UIFnPresetV1 {
  try {
    return normalizePreset(JSON.parse(source) as UIFnPresetInput);
  } catch (cause) {
    if (cause instanceof UIFnPresetError) throw cause;
    throw new UIFnPresetError('UIFN_PRESET_INVALID_JSON', 'Preset JSON could not be parsed.');
  }
}

export function redactPreset(preset: UIFnPresetV1): UIFnPresetV1 {
  return { ...normalizePreset(preset) };
}
export const PRESET_SCHEMA_VERSION = 1 as const;
export const PRESET_CODE_PREFIX = 'uifn1_';
export const PRESET_CREATE_ORIGIN = 'https://uifn.dev/create';
export const PRESET_OWNER = 'uifn-maintainer';

export const PRESET_AXES = {
  style: ['nova', 'meridian', 'atlas'],
  baseColor: ['zinc', 'slate', 'stone', 'neutral', 'gray', 'mauve'],
  theme: ['default', 'high-contrast'],
  chartColor: ['spectrum', 'earth', 'ocean', 'sunset'],
  font: ['inter', 'source-sans', 'ibm-plex-sans', 'literata'],
  headingFont: ['inherit', 'inter', 'source-serif', 'space-grotesk'],
  iconLibrary: ['lucide', 'phosphor', 'heroicons'],
  radius: ['none', 'sm', 'md', 'lg', 'xl'],
  density: ['compact', 'comfortable', 'spacious'],
  menuTreatment: ['inset', 'bordered', 'elevated'],
  framework: ['react', 'svelte', 'solid'],
  installMode: ['package', 'source'],
} as const;

export const PRESET_FIELD_ORDER = [
  'style',
  'baseColor',
  'theme',
  'chartColor',
  'font',
  'headingFont',
  'iconLibrary',
  'radius',
  'density',
  'menuTreatment',
  'framework',
  'installMode',
] as const;

export type PresetAxis = keyof typeof PRESET_AXES;
export type PresetAxisValue<K extends PresetAxis> = (typeof PRESET_AXES)[K][number];

export interface UIFnPresetV1 {
  version: 1;
  style: PresetAxisValue<'style'>;
  baseColor: PresetAxisValue<'baseColor'>;
  theme: PresetAxisValue<'theme'>;
  chartColor: PresetAxisValue<'chartColor'>;
  font: PresetAxisValue<'font'>;
  headingFont: PresetAxisValue<'headingFont'>;
  iconLibrary: PresetAxisValue<'iconLibrary'>;
  radius: PresetAxisValue<'radius'>;
  density: PresetAxisValue<'density'>;
  menuTreatment: PresetAxisValue<'menuTreatment'>;
  framework: PresetAxisValue<'framework'>;
  installMode: PresetAxisValue<'installMode'>;
}

export type UIFnPresetInput = Partial<Omit<UIFnPresetV1, 'version'>> & { version?: number };

export const PRESET_DEFAULTS: UIFnPresetV1 = {
  version: 1,
  style: 'nova',
  baseColor: 'zinc',
  theme: 'default',
  chartColor: 'spectrum',
  font: 'inter',
  headingFont: 'inherit',
  iconLibrary: 'lucide',
  radius: 'md',
  density: 'comfortable',
  menuTreatment: 'elevated',
  framework: 'react',
  installMode: 'package',
};

export const PRESET_AXIS_LABELS: Record<PresetAxis, string> = {
  style: 'Style family',
  baseColor: 'Base color',
  theme: 'Semantic theme',
  chartColor: 'Chart palette',
  font: 'Body font',
  headingFont: 'Heading font',
  iconLibrary: 'Icon library',
  radius: 'Radius',
  density: 'Density',
  menuTreatment: 'Menu treatment',
  framework: 'Framework',
  installMode: 'Install mode',
};

export const APPROVED_SUPPORT_MATRIX = {
  templates: ['react-vite'] as const,
  frameworks: ['react'] as const,
  packageManagers: ['npm'] as const,
  installModes: ['package', 'source'] as const,
  partialDomains: ['theme', 'font'] as const,
  encoding: 'self-contained' as const,
  compatibility: 'V1 codes remain decodable for the life of schema version 1. Unknown future versions fail closed.',
};

export type ApprovedTemplate = (typeof APPROVED_SUPPORT_MATRIX.templates)[number];
export type PartialPresetDomain = (typeof APPROVED_SUPPORT_MATRIX.partialDomains)[number];

export const PILOT_ARTIFACTS = [
  'button',
  'field',
  'input',
  'checkbox',
  'switch',
  'select',
  'dialog',
  'menu',
  'tabs',
  'card',
  'table',
] as const;
import {
  PRESET_AXES,
  PRESET_AXIS_LABELS,
  PRESET_DEFAULTS,
  PRESET_FIELD_ORDER,
  compilePreset,
  encodePreset,
  fixtureCss,
  fixtureMarkup,
  normalizePreset,
  presetFromUrl,
  randomPreset,
  themeTokenDocument,
  type PresetAxis,
  type UIFnPresetV1,
} from '@uifn/registry/preset';

const VIEWPORTS = {
  desktop: 1120,
  tablet: 768,
  mobile: 390,
} as const;

function parseState(): UIFnPresetV1 {
  try {
    return presetFromUrl(window.location.href);
  } catch {
    return { ...PRESET_DEFAULTS };
  }
}

function optionControl(axis: PresetAxis, preset: UIFnPresetV1, locked: Set<PresetAxis>): string {
  const options = (PRESET_AXES[axis] as readonly string[]).map((value) => `<option value="${value}" ${preset[axis] === value ? 'selected' : ''}>${value}</option>`).join('');
  return `<label class="axis">
    <span>
      <input type="checkbox" data-lock="${axis}" ${locked.has(axis) ? 'checked' : ''} />
      ${PRESET_AXIS_LABELS[axis]}
    </span>
    <select data-axis="${axis}">${options}</select>
  </label>`;
}

function render(preset: UIFnPresetV1, locked: Set<PresetAxis>, mode: 'light' | 'dark', viewport: keyof typeof VIEWPORTS) {
  const plan = compilePreset(preset);
  const tokens = themeTokenDocument(preset);
  const app = document.querySelector('#app');
  if (!app) return;
  app.innerHTML = `
    <header class="shell-header">
      <div>
        <p class="kicker">uifn Create</p>
        <h1>Versioned presets</h1>
      </div>
      <div class="header-actions">
        <button type="button" data-action="random">Randomize unlocked</button>
        <button type="button" data-action="copy-code">Copy code</button>
        <button type="button" data-action="copy-url">Copy URL</button>
      </div>
    </header>
    <main class="layout">
      <form class="controls" aria-label="Preset axes">
        ${PRESET_FIELD_ORDER.map((axis: PresetAxis) => optionControl(axis, preset, locked)).join('')}
      </form>
      <section class="preview-pane">
        <div class="preview-toolbar">
          <div class="segmented" role="group" aria-label="Color mode">
            <button type="button" data-mode="light" ${mode === 'light' ? 'aria-pressed="true"' : 'aria-pressed="false"'}>Light</button>
            <button type="button" data-mode="dark" ${mode === 'dark' ? 'aria-pressed="true"' : 'aria-pressed="false"'}>Dark</button>
          </div>
          <div class="segmented" role="group" aria-label="Viewport">
            ${Object.keys(VIEWPORTS).map((name) => `<button type="button" data-viewport="${name}" ${viewport === name ? 'aria-pressed="true"' : 'aria-pressed="false"'}>${name}</button>`).join('')}
          </div>
        </div>
        <div class="preview-frame" data-mode="${mode}" style="width:${VIEWPORTS[viewport]}px">
          <style>${plan.css.light}${plan.css.dark}${fixtureCss()}</style>
          <div class="preview-root" data-uifn-mode="${mode}">${fixtureMarkup(plan)}</div>
        </div>
        <section class="outputs">
          <article>
            <h2>New project</h2>
            <pre><code>${plan.commands.init}</code></pre>
