import {
  DATAFN_NAMESPACE_STORAGE_MANIFEST_VERSION,
  DATAFN_NAMESPACE_STORAGE_SCHEMA_VERSION,
  assertSupportedNamespaceStorageVersions,
  getRelationJoinTableName,
  isNamespaced,
  namespaceStorageManifestEntry,
  resolveCapabilities,
