+  it('normalizes defaults and produces one deterministic code for equivalent input', () => {
+    expect(normalizePreset({})).toEqual(UIFN_PRESET_DEFAULTS);
+    expect(encodePreset({})).toBe(encodePreset({ version: 1, fonts: {}, target: {} }));
