+import fs from "node:fs";
+import os from "node:os";
+import path from "node:path";
+import { afterEach, describe, expect, it } from "vitest";
+import {
+  decodePreset,
+  encodePreset,
+  normalizePreset,
+  presetUrl,
+  resolveProjectPreset,
+  UIFN_PRESET_V1_DEFAULTS,
+} from "../preset";
+import { runCli } from "../cli";
+
+const roots: string[] = [];
+afterEach(() =>
+  roots
+    .splice(0)
+    .forEach((root) => fs.rmSync(root, { recursive: true, force: true })),
+);
+
+describe("UIFnPresetV1", () => {
+  it("normalizes equivalent inputs to one deterministic, versioned code", () => {
+    const partial = { theme: "emerald" as const, style: "signal" as const };
+    const complete = { ...UIFN_PRESET_V1_DEFAULTS, ...partial };
+    expect(encodePreset(partial)).toBe(encodePreset(complete));
+    expect(decodePreset(encodePreset(partial))).toEqual(complete);
+  });
+
+  it("fails closed for unknown fields, options, malformed codes, and future versions", () => {
+    expect(() => normalizePreset({ surprise: true })).toThrow(
+      "Unknown preset field",
+    );
+    expect(() => normalizePreset({ theme: "blue" })).toThrow(
+      "Unsupported theme option",
+    );
+    expect(() => decodePreset("uifn1_not-json")).toThrow("invalid payload");
+    expect(() => decodePreset("uifn2_abc")).toThrow("unsupported version");
+  });
+
+  it("round-trips through URLs and canonical project state", () => {
+    const root = fs.mkdtempSync(path.join(os.tmpdir(), "uifn-preset-"));
+    roots.push(root);
+    fs.mkdirSync(path.join(root, ".uifn"));
+    fs.writeFileSync(
+      path.join(root, ".uifn/preset.json"),
+      JSON.stringify({ radius: "large" }),
+    );
+    const resolved = resolveProjectPreset(root);
+    expect(resolved.preset.radius).toBe("large");
+    expect(new URL(presetUrl(resolved.code)).searchParams.get("preset")).toBe(
+      resolved.code,
+    );
+  });
+
+  it("supports inspectable CLI encode, decode, URL, and project resolve operations", async () => {
+    const output: string[] = [];
+    const encoded = await runCli(
+      ["preset", "encode", '{"density":"compact"}', "--json"],
+      { stdout: (line) => output.push(line) },
+    );
+    expect(encoded.exitCode).toBe(0);
+    const code = (encoded.result as { code: string }).code;
+    expect(
+      (await runCli(["preset", "decode", code], { stdout: () => undefined }))
+        .exitCode,
+    ).toBe(0);
+    expect(
+      (await runCli(["preset", "url", code], { stdout: () => undefined }))
+        .exitCode,
+    ).toBe(0);
+  });
+});
