@@ -0,0 +1,119 @@
+import { existsSync, readFileSync } from 'node:fs';
+import path from 'node:path';
+
+export const UIFN_PRESET_VERSION = 1 as const;
+export const UIFN_PRESET_CODE_PREFIX = 'uifn1_' as const;
+
+export const UIFN_PRESET_OPTIONS = {
+  style: ['atlas', 'studio', 'signal'],
+  baseColor: ['slate', 'gray', 'zinc', 'neutral', 'stone', 'mauve'],
+  theme: ['indigo', 'blue', 'violet', 'emerald', 'amber', 'rose'],
+  chartPalette: ['categorical', 'sequential', 'warm', 'cool'],
+  bodyFont: ['inter', 'system', 'source-sans-3'],
+  headingFont: ['inter', 'system', 'space-grotesk'],
+  icons: ['lucide', 'phosphor'],
+  radius: ['none', 'sm', 'md', 'lg', 'full'],
+  density: ['compact', 'comfortable', 'spacious'],
+  menu: ['solid', 'subtle', 'transparent'],
+  framework: ['react', 'svelte', 'solid'],
+  template: ['react-vite'],
+  packageManager: ['npm'],
+  installMode: ['package', 'source'],
+} as const;
+
+type Option<K extends keyof typeof UIFN_PRESET_OPTIONS> = (typeof UIFN_PRESET_OPTIONS)[K][number];
+export interface UIFnPresetV1 {
+  version: 1;
+  style: Option<'style'>;
+  baseColor: Option<'baseColor'>;
+  theme: Option<'theme'>;
+  chartPalette: Option<'chartPalette'>;
+  fonts: { body: Option<'bodyFont'>; heading: Option<'headingFont'> };
+  icons: Option<'icons'>;
+  radius: Option<'radius'>;
+  density: Option<'density'>;
+  menu: Option<'menu'>;
+  target: { framework: Option<'framework'>; template: Option<'template'>; packageManager: Option<'packageManager'>; installMode: Option<'installMode'> };
+}
+
+export const UIFN_PRESET_DEFAULTS: Readonly<UIFnPresetV1> = Object.freeze({
+  version: 1, style: 'atlas', baseColor: 'slate', theme: 'indigo', chartPalette: 'categorical',
+  fonts: Object.freeze({ body: 'inter', heading: 'space-grotesk' }), icons: 'lucide', radius: 'md',
+  density: 'comfortable', menu: 'subtle',
+  target: Object.freeze({ framework: 'react', template: 'react-vite', packageManager: 'npm', installMode: 'package' }),
+});
+
+export class UIFnPresetError extends Error {
+  constructor(public readonly code: 'UIFN_PRESET_INVALID' | 'UIFN_PRESET_UNSUPPORTED_VERSION', message: string) { super(message); this.name = 'UIFnPresetError'; }
+}
+
+function record(value: unknown, location: string): Record<string, unknown> {
+  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new UIFnPresetError('UIFN_PRESET_INVALID', `${location} must be an object.`);
+  return value as Record<string, unknown>;
+}
+function keys(value: Record<string, unknown>, allowed: readonly string[], location: string) {
+  const unknown = Object.keys(value).filter((key) => !allowed.includes(key));
+  if (unknown.length) throw new UIFnPresetError('UIFN_PRESET_INVALID', `Unknown ${location} field: ${unknown.sort()[0]}.`);
+}
+function option<K extends keyof typeof UIFN_PRESET_OPTIONS>(key: K, value: unknown, fallback: Option<K>): Option<K> {
+  const selected = value ?? fallback;
+  if (!(UIFN_PRESET_OPTIONS[key] as readonly unknown[]).includes(selected)) throw new UIFnPresetError('UIFN_PRESET_INVALID', `Unsupported ${key}: ${String(selected)}.`);
+  return selected as Option<K>;
+}
+
+/** Validate and expand a partial V1 preset into the canonical, stable key order. */
+export function normalizePreset(input: unknown = {}): UIFnPresetV1 {
+  const root = record(input, 'preset');
+  keys(root, ['version', 'style', 'baseColor', 'theme', 'chartPalette', 'fonts', 'icons', 'radius', 'density', 'menu', 'target'], 'preset');
+  if (root.version !== undefined && root.version !== 1) throw new UIFnPresetError('UIFN_PRESET_UNSUPPORTED_VERSION', `Unsupported preset version: ${String(root.version)}.`);
+  const fonts = root.fonts === undefined ? {} : record(root.fonts, 'fonts');
+  const target = root.target === undefined ? {} : record(root.target, 'target');
+  keys(fonts, ['body', 'heading'], 'fonts'); keys(target, ['framework', 'template', 'packageManager', 'installMode'], 'target');
+  return {
+    version: 1,
+    style: option('style', root.style, UIFN_PRESET_DEFAULTS.style),
+    baseColor: option('baseColor', root.baseColor, UIFN_PRESET_DEFAULTS.baseColor),
+    theme: option('theme', root.theme, UIFN_PRESET_DEFAULTS.theme),
+    chartPalette: option('chartPalette', root.chartPalette, UIFN_PRESET_DEFAULTS.chartPalette),
+    fonts: { body: option('bodyFont', fonts.body, UIFN_PRESET_DEFAULTS.fonts.body), heading: option('headingFont', fonts.heading, UIFN_PRESET_DEFAULTS.fonts.heading) },
+    icons: option('icons', root.icons, UIFN_PRESET_DEFAULTS.icons), radius: option('radius', root.radius, UIFN_PRESET_DEFAULTS.radius),
+    density: option('density', root.density, UIFN_PRESET_DEFAULTS.density), menu: option('menu', root.menu, UIFN_PRESET_DEFAULTS.menu),
+    target: { framework: option('framework', target.framework, UIFN_PRESET_DEFAULTS.target.framework), template: option('template', target.template, UIFN_PRESET_DEFAULTS.target.template), packageManager: option('packageManager', target.packageManager, UIFN_PRESET_DEFAULTS.target.packageManager), installMode: option('installMode', target.installMode, UIFN_PRESET_DEFAULTS.target.installMode) },
+  };
+}
+
+export function encodePreset(input: unknown = {}): string {
+  return UIFN_PRESET_CODE_PREFIX + Buffer.from(JSON.stringify(normalizePreset(input)), 'utf8').toString('base64url');
+}
+export function decodePreset(code: string): UIFnPresetV1 {
+  const match = /^uifn(\d+)_([A-Za-z0-9_-]+)$/.exec(code);
+  if (!match) throw new UIFnPresetError('UIFN_PRESET_INVALID', 'Invalid preset code.');
+  if (match[1] !== '1') throw new UIFnPresetError('UIFN_PRESET_UNSUPPORTED_VERSION', `Unsupported preset code version: ${match[1]}.`);
+  try {
+    const bytes = Buffer.from(match[2], 'base64url');
+    // Node's base64url decoder is intentionally permissive. Re-encoding makes
+    // malformed and non-canonical payloads fail closed instead of aliasing a
+    // valid preset code.
+    if (bytes.toString('base64url') !== match[2]) throw new UIFnPresetError('UIFN_PRESET_INVALID', 'Preset payload is not canonical base64url.');
+    return normalizePreset(JSON.parse(bytes.toString('utf8')));
+  }
+  catch (error) { if (error instanceof UIFnPresetError) throw error; throw new UIFnPresetError('UIFN_PRESET_INVALID', 'Preset payload is not valid JSON.'); }
+}
+export function presetUrl(input: string | unknown, origin = 'https://uifn.dev/create'): string {
+  const code = typeof input === 'string' ? encodePreset(decodePreset(input)) : encodePreset(input);
+  const url = new URL(origin); url.searchParams.set('preset', code); return url.toString();
+}
+export function decodePresetUrl(value: string | URL): UIFnPresetV1 {
+  let url: URL;
+  try { url = value instanceof URL ? value : new URL(value); }
+  catch { throw new UIFnPresetError('UIFN_PRESET_INVALID', 'Invalid preset URL.'); }
+  const code = url.searchParams.get('preset');
+  if (!code) throw new UIFnPresetError('UIFN_PRESET_INVALID', 'Preset URL is missing the preset query parameter.');
+  return decodePreset(code);
+}
+export function resolveProjectPreset(rootDir = process.cwd()): UIFnPresetV1 {
+  const filename = path.join(rootDir, '.uifn', 'preset.json');
+  if (!existsSync(filename)) throw new UIFnPresetError('UIFN_PRESET_INVALID', 'No .uifn/preset.json was found.');
+  try { return normalizePreset(JSON.parse(readFileSync(filename, 'utf8'))); }
+  catch (error) { if (error instanceof UIFnPresetError) throw error; throw new UIFnPresetError('UIFN_PRESET_INVALID', '.uifn/preset.json is not valid JSON.'); }
+}

