+import fs from "node:fs";
+import os from "node:os";
+import path from "node:path";
+import { afterEach, describe, expect, it } from "vitest";
+import {
+  decodePreset,
+  encodePreset,
+  normalizePreset,
+  presetUrl,
+  resolveProjectPreset,
+  UIFN_PRESET_V1_DEFAULTS,
+} from "../preset";
+import { runCli } from "../cli";
+
+const roots: string[] = [];
+afterEach(() =>
+  roots
+    .splice(0)
+    .forEach((root) => fs.rmSync(root, { recursive: true, force: true })),
+);
+
+describe("UIFnPresetV1", () => {
+  it("normalizes equivalent inputs to one deterministic, versioned code", () => {
+    const partial = { theme: "emerald" as const, style: "signal" as const };
+    const complete = { ...UIFN_PRESET_V1_DEFAULTS, ...partial };
+    expect(encodePreset(partial)).toBe(encodePreset(complete));
+    expect(decodePreset(encodePreset(partial))).toEqual(complete);
+  });
+
+  it("fails closed for unknown fields, options, malformed codes, and future versions", () => {
+    expect(() => normalizePreset({ surprise: true })).toThrow(
+      "Unknown preset field",
+    );
+    expect(() => normalizePreset({ theme: "blue" })).toThrow(
+      "Unsupported theme option",
+    );
+    expect(() => decodePreset("uifn1_not-json")).toThrow("invalid payload");
+    expect(() => decodePreset("uifn2_abc")).toThrow("unsupported version");
+  });
