+  it("round-trips through URLs and canonical project state", () => {
+    const root = fs.mkdtempSync(path.join(os.tmpdir(), "uifn-preset-"));
+    roots.push(root);
+    fs.mkdirSync(path.join(root, ".uifn"));
+    fs.writeFileSync(
+      path.join(root, ".uifn/preset.json"),
+      JSON.stringify({ radius: "large" }),
+    );
+    const resolved = resolveProjectPreset(root);
+    expect(resolved.preset.radius).toBe("large");
+    expect(new URL(presetUrl(resolved.code)).searchParams.get("preset")).toBe(
+      resolved.code,
+    );
+  });
+
+  it("supports inspectable CLI encode, decode, URL, and project resolve operations", async () => {
+    const output: string[] = [];
+    const encoded = await runCli(
