+import fs from "node:fs";
+import path from "node:path";
+
+/** The stable, portable configuration contract shared by Create and the CLI. */
+export interface UIFnPresetV1 {
+  version: 1;
+  style: "atlas" | "signal" | "studio";
+  baseColor: "gray" | "mauve" | "slate" | "sand";
+  theme: "neutral" | "indigo" | "emerald" | "amber";
+  chartPalette: "categorical" | "sequential" | "warm";
+  bodyFont: "inter" | "system" | "source-sans-3";
+  headingFont: "inherit" | "manrope" | "space-grotesk";
+  icons: "lucide" | "phosphor";
+  radius: "none" | "small" | "medium" | "large";
+  density: "compact" | "comfortable" | "spacious";
+  menu: "solid" | "subtle" | "transparent";
+  framework: "react" | "svelte" | "solid";
+  installMode: "package" | "source";
+}
+
+export const PRESET_CODE_PREFIX = "uifn1_" as const;
+export const PRESET_PROJECT_PATH = ".uifn/preset.json" as const;
+
+export const UIFN_PRESET_V1_OPTIONS = Object.freeze({
+  style: ["atlas", "signal", "studio"],
+  baseColor: ["gray", "mauve", "slate", "sand"],
+  theme: ["neutral", "indigo", "emerald", "amber"],
+  chartPalette: ["categorical", "sequential", "warm"],
+  bodyFont: ["inter", "system", "source-sans-3"],
+  headingFont: ["inherit", "manrope", "space-grotesk"],
+  icons: ["lucide", "phosphor"],
+  radius: ["none", "small", "medium", "large"],
+  density: ["compact", "comfortable", "spacious"],
+  menu: ["solid", "subtle", "transparent"],
+  framework: ["react", "svelte", "solid"],
+  installMode: ["package", "source"],
+} as const);
+
+export const UIFN_PRESET_V1_DEFAULTS: Readonly<UIFnPresetV1> = Object.freeze({
+  version: 1,
+  style: "atlas",
+  baseColor: "slate",
+  theme: "indigo",
+  chartPalette: "categorical",
+  bodyFont: "inter",
+  headingFont: "inherit",
+  icons: "lucide",
+  radius: "medium",
+  density: "comfortable",
+  menu: "subtle",
+  framework: "react",
+  installMode: "package",
+});
+
+export type PresetInput = Partial<Omit<UIFnPresetV1, "version">> & {
+  version?: 1;
+};
+export type PresetErrorCode =
+  | "UIFN_PRESET_INVALID"
+  | "UIFN_PRESET_UNSUPPORTED_VERSION"
+  | "UIFN_PRESET_NOT_FOUND";
+export class PresetError extends Error {
+  readonly code: PresetErrorCode;
+
+  constructor(code: PresetErrorCode, message: string) {
+    super(message);
+    this.name = "PresetError";
+    this.code = code;
+  }
+}
+
+const fields = Object.keys(UIFN_PRESET_V1_DEFAULTS) as (keyof UIFnPresetV1)[];
+
+/** Strictly validates input and fills omitted fields with deterministic V1 defaults. */
+export function normalizePreset(input: unknown): UIFnPresetV1 {
+  if (!input || typeof input !== "object" || Array.isArray(input))
+    throw new PresetError("UIFN_PRESET_INVALID", "Preset must be an object.");
+  const value = input as Record<string, unknown>;
+  const unknown = Object.keys(value).filter(
+    (key) => !fields.includes(key as keyof UIFnPresetV1),
+  );
+  if (unknown.length)
+    throw new PresetError(
+      "UIFN_PRESET_INVALID",
+      `Unknown preset field: ${unknown.sort()[0]}`,
+    );
+  if (value.version !== undefined && value.version !== 1)
+    throw new PresetError(
+      "UIFN_PRESET_UNSUPPORTED_VERSION",
+      `Unsupported preset version: ${String(value.version)}`,
+    );
+  const result = { ...UIFN_PRESET_V1_DEFAULTS, ...value } as UIFnPresetV1;
+  for (const [key, options] of Object.entries(UIFN_PRESET_V1_OPTIONS)) {
+    if (
+      !(options as readonly unknown[]).includes(
+        result[key as keyof UIFnPresetV1],
+      )
+    ) {
+      throw new PresetError(
+        "UIFN_PRESET_INVALID",
+        `Unsupported ${key} option: ${String(result[key as keyof UIFnPresetV1])}`,
+      );
+    }
+  }
+  return result;
+}
+
+function canonicalJson(preset: UIFnPresetV1): string {
+  return JSON.stringify(
+    Object.fromEntries(fields.map((key) => [key, preset[key]])),
+  );
+}
+
+export function encodePreset(input: unknown = {}): string {
+  return (
+    PRESET_CODE_PREFIX +
+    Buffer.from(canonicalJson(normalizePreset(input)), "utf8").toString(
+      "base64url",
+    )
+  );
+}
+
+export function decodePreset(code: string): UIFnPresetV1 {
+  if (!code.startsWith("uifn"))
+    throw new PresetError(
+      "UIFN_PRESET_INVALID",
+      "Preset code has an invalid prefix.",
+    );
+  if (!code.startsWith(PRESET_CODE_PREFIX))
+    throw new PresetError(
+      "UIFN_PRESET_UNSUPPORTED_VERSION",
+      "Preset code uses an unsupported version.",
+    );
+  try {
+    const encoded = code.slice(PRESET_CODE_PREFIX.length);
+    if (!encoded || !/^[A-Za-z0-9_-]+$/.test(encoded))
+      throw new Error("invalid base64url");
+    const preset = normalizePreset(
+      JSON.parse(Buffer.from(encoded, "base64url").toString("utf8")),
+    );
+    if (encodePreset(preset) !== code)
+      throw new PresetError(
+        "UIFN_PRESET_INVALID",
+        "Preset code is not canonically encoded.",
+      );
+    return preset;
+  } catch (cause) {
+    if (cause instanceof PresetError) throw cause;
+    throw new PresetError(
+      "UIFN_PRESET_INVALID",
+      "Preset code contains an invalid payload.",
+    );
+  }
+}
+
+export function presetUrl(
+  input: unknown,
+  baseUrl = "https://uifn.dev/create",
+): string {
+  const url = new URL(baseUrl);
+  url.searchParams.set(
+    "preset",
+    typeof input === "string"
+      ? encodePreset(decodePreset(input))
+      : encodePreset(input),
+  );
+  return url.toString();
+}
+
+/** Resolves and verifies canonical project state without searching parent directories. */
+export function resolveProjectPreset(rootDir = process.cwd()): {
+  preset: UIFnPresetV1;
+  code: string;
+  path: string;
+} {
+  const presetPath = path.join(path.resolve(rootDir), PRESET_PROJECT_PATH);
+  if (!fs.existsSync(presetPath))
+    throw new PresetError(
+      "UIFN_PRESET_NOT_FOUND",
+      `No ${PRESET_PROJECT_PATH} exists in this project.`,
+    );
+  let raw: unknown;
+  try {
+    raw = JSON.parse(fs.readFileSync(presetPath, "utf8"));
+  } catch {
+    throw new PresetError(
+      "UIFN_PRESET_INVALID",
+      `${PRESET_PROJECT_PATH} is not valid JSON.`,
+    );
+  }
+  const preset = normalizePreset(raw);
+  return { preset, code: encodePreset(preset), path: PRESET_PROJECT_PATH };
+}
