  1	import type { DatafnSchema } from "./core-types.js";
  2	
  3	/** Version of the structural request-envelope contract used by this module. */
  4	export const DATAFN_PROTOCOL_ENVELOPE_VERSION = 1 as const;
  5	
  6	export type DatafnProtocolEnvelopeVersion =
  7	  typeof DATAFN_PROTOCOL_ENVELOPE_VERSION;
  8	
  9	export type DatafnResourceSelector = string;
 10	
 11	export type DatafnSelectorAction =
 12	  | "status"
 13	  | "query"
 14	  | "mutation"
 15	  | "transact"
 16	  | "seed"
 17	  | "clone"
 18	  | "pull"
 19	  | "push"
 20	  | "reconcile"
 21	  | "search";
 22	
 23	/**
 24	 * Transport-neutral input for security-sensitive selector extraction.
 25	 * `action` must come from the matched DataFn route, never from request data.
 26	 */
 27	export interface DatafnResourceSelectorEnvelope {
 28	  readonly version: number;
 29	  readonly action: DatafnSelectorAction;
 30	  readonly payload: unknown;
 31	}
 32	
 33	/** A structurally parsed envelope whose selectors have been schema-validated. */
 34	export interface DatafnParsedResourceSelectorEnvelope {
 35	  readonly version: DatafnProtocolEnvelopeVersion;
 36	  readonly action: DatafnSelectorAction;
 37	  readonly selectors: readonly DatafnResourceSelector[];
 38	}
 39	
 40	export type DatafnResourceSelectorErrorCode =
 41	  | "DATAFN_UNSUPPORTED_ENVELOPE_VERSION"
 42	  | "DFQL_INVALID"
 43	  | "DFQL_UNKNOWN_RESOURCE";
 44	
 45	export class DatafnResourceSelectorError extends Error {
 46	  readonly code: DatafnResourceSelectorErrorCode;
 47	  readonly path: string;
 48	
 49	  constructor(
 50	    code: DatafnResourceSelectorErrorCode,
 51	    message: string,
 52	    path = "$",
 53	  ) {
 54	    super(message);
 55	    this.name = "DatafnResourceSelectorError";
 56	    this.code = code;
 57	    this.path = path;
 58	  }
 59	}
 60	
 61	function invalid(message: string, path = "$"): never {
 62	  throw new DatafnResourceSelectorError("DFQL_INVALID", message, path);
 63	}
 64	
 65	function objectAt(value: unknown, path: string): Record<string, unknown> {
 66	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
 67	    invalid("Invalid DataFn protocol shape: expected object", path);
 68	  }
 69	  return value as Record<string, unknown>;
 70	}
 71	
 72	function selectorAt(
 73	  value: unknown,
 74	  path: string,
 75	  knownResources: ReadonlySet<string>,
 76	): string {
 77	  if (typeof value !== "string" || value.trim().length === 0) {
 78	    invalid(
 79	      "Invalid DataFn resource selector: expected non-empty string",
 80	      path,
 81	    );
 82	  }
 83	  if (!knownResources.has(value)) {
 84	    throw new DatafnResourceSelectorError(
 85	      "DFQL_UNKNOWN_RESOURCE",
 86	      `Unknown resource: ${value}`,
 87	      path,
 88	    );
 89	  }
 90	  return value;
 91	}
 92	
 93	function arrayAt(value: unknown, path: string): readonly unknown[] {
 94	  if (!Array.isArray(value)) {
 95	    invalid("Invalid DataFn protocol shape: expected array", path);
 96	  }
 97	  return value;
 98	}
 99	
100	/**
101	 * Parses only protocol structure that can carry resource selectors. It never
102	 * descends into application records, filters, values, relations, or metadata.
103	 */
104	export function parseDatafnResourceSelectorEnvelope(
105	  envelope: DatafnResourceSelectorEnvelope,
106	  schema: DatafnSchema,
107	): DatafnParsedResourceSelectorEnvelope {
108	  if (envelope.version !== DATAFN_PROTOCOL_ENVELOPE_VERSION) {
109	    throw new DatafnResourceSelectorError(
110	      "DATAFN_UNSUPPORTED_ENVELOPE_VERSION",
111	      `Unsupported DataFn protocol envelope version: ${String(envelope.version)}`,
112	      "version",
113	    );
114	  }
115	
116	  const knownResources = new Set(
117	    schema.resources.map((resource) => resource.name),
118	  );
119	  const selectors: string[] = [];
120	  const seen = new Set<string>();
121	  const add = (value: unknown, path: string) => {
122	    const selector = selectorAt(value, path, knownResources);
123	    if (!seen.has(selector)) {
124	      seen.add(selector);
125	      selectors.push(selector);
126	    }
127	  };
128	  const addAll = () => {
129	    for (const resource of schema.resources)
130	      add(resource.name, "schema.resources");
131	  };
132	  const parseOperation = (value: unknown, path: string) => {
133	    const operation = objectAt(value, path);
134	    add(operation.resource, `${path}.resource`);
135	  };
136	  const parseOperationBody = (value: unknown, path: string) => {
137	    if (Array.isArray(value)) {
138	      value.forEach((entry, index) =>
139	        parseOperation(entry, `${path}[${index}]`),
140	      );
141	      return;
142	    }
143	    parseOperation(value, path);
144	  };
145	
146	  switch (envelope.action) {
147	    case "query":
148	    case "mutation":
149	      parseOperationBody(envelope.payload, "payload");
150	      break;
151	    case "transact": {
152	      const payload = objectAt(envelope.payload, "payload");
153	      const steps = arrayAt(payload.steps, "payload.steps");
154	      steps.forEach((value, index) => {
155	        const path = `payload.steps[${index}]`;
156	        const step = objectAt(value, path);
157	        const hasQuery = step.query !== undefined;
158	        const hasMutation = step.mutation !== undefined;
159	        if (hasQuery && hasMutation) {
160	          invalid(
161	            "Invalid DataFn transaction step: expected one operation",
162	            path,
163	          );
164	        }
165	        if (hasQuery) parseOperation(step.query, `${path}.query`);
166	        else if (hasMutation) parseOperation(step.mutation, `${path}.mutation`);
167	        else parseOperation(step, path);
168	      });
169	      break;
170	    }
171	    case "push": {
172	      const payload = objectAt(envelope.payload, "payload");
173	      arrayAt(payload.mutations, "payload.mutations").forEach(
174	        (mutation, index) =>
175	          parseOperation(mutation, `payload.mutations[${index}]`),
176	      );
177	      break;
178	    }
179	    case "search": {
180	      const payload = objectAt(envelope.payload, "payload");
181	      if (payload.resources === undefined) addAll();
182	      else
183	        arrayAt(payload.resources, "payload.resources").forEach(
184	          (resource, index) => add(resource, `payload.resources[${index}]`),
185	        );
186	      break;
187	    }
188	    case "reconcile": {
189	      const payload = objectAt(envelope.payload, "payload");
190	      arrayAt(payload.resources, "payload.resources").forEach(
191	        (resource, index) => add(resource, `payload.resources[${index}]`),
192	      );
193	      break;
194	    }
195	    case "clone": {
196	      const payload = objectAt(envelope.payload, "payload");
197	      if (payload.tables === undefined) addAll();
198	      else
199	        arrayAt(payload.tables, "payload.tables").forEach((resource, index) =>
200	          add(resource, `payload.tables[${index}]`),
201	        );
202	      break;
203	    }
204	    case "pull":
205	      objectAt(envelope.payload, "payload");
206	      addAll();
207	      break;
208	    case "status":
209	    case "seed":
210	      objectAt(envelope.payload, "payload");
211	      break;
212	    default: {
213	      const exhaustive: never = envelope.action;
214	      invalid(`Unsupported DataFn action: ${String(exhaustive)}`, "action");
215	    }
216	  }
217	
218	  return Object.freeze({
219	    version: DATAFN_PROTOCOL_ENVELOPE_VERSION,
220	    action: envelope.action,
221	    selectors: Object.freeze(selectors),
222	  });
223	}
224	
225	/**
226	 * Supported security-sensitive integration point for gateways and plugins.
227	 * Returns normalized, stable-order, deduplicated resource names.
228	 */
229	export function extractDatafnResourceSelectors(
230	  envelope: DatafnResourceSelectorEnvelope,
231	  schema: DatafnSchema,
232	): readonly DatafnResourceSelector[] {
233	  return parseDatafnResourceSelectorEnvelope(envelope, schema).selectors;
234	}

